# Restore Windows 11 File Explorer Write-Host "Restoring Windows 11 File Explorer..." -ForegroundColor Cyan Remove-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Shell Extensions\Blocked" -Name "{e2bf4bde-6dbf-4b1b-867e-5b7d8a9be425}" -ErrorAction SilentlyContinue # Hide file extensions (default) Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "HideFileExt" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue # Hide hidden files (default) Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "Hidden" -Value 2 -Type DWord -Force -ErrorAction SilentlyContinue # Restart Explorer Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue Start-Sleep -Seconds 2 Start-Process explorer Write-Host "Windows 11 File Explorer has been restored." -ForegroundColor Green